package com.example.grpc.pool

import io.grpc.{ManagedChannel, ManagedChannelBuilder, StatusRuntimeException}
import io.grpc.stub.StreamObserver
import java.util.concurrent.{ConcurrentHashMap, TimeUnit, atomic}
import java.util.concurrent.atomic.{AtomicInteger, AtomicReference, AtomicBoolean}
import scala.collection.mutable
import scala.concurrent.{Future, Promise, ExecutionContext}
import scala.util.{Try, Success, Failure}

case class PoolConfig(maxSize: Int = 10, idleTimeoutMs: Long = 30000, healthCheckIntervalMs: Long = 5000)

sealed trait ConnectionState
case object Available extends ConnectionState
case object InUse extends ConnectionState
case object Draining extends ConnectionState
case object Closed extends ConnectionState

class PooledConnection(val channel: ManagedChannel, val id: Int) {
  val state: AtomicReference[ConnectionState] = new AtomicReference[ConnectionState](Available)
  val lastUsed: AtomicReference[Long] = new AtomicReference[Long](System.currentTimeMillis())
  val activeRequests: AtomicInteger = new AtomicInteger(0)
  val authenticated: AtomicBoolean = new AtomicBoolean(false)
  @volatile var ownerToken: String = null

  def markInUse(token: String): Boolean = {
    if (state.compareAndSet(Available, InUse)) {
      ownerToken = token
      activeRequests.incrementAndGet()
      lastUsed.set(System.currentTimeMillis())
      true
    } else false
  }

  def release(token: String): Unit = {
    if (ownerToken == token) {
      activeRequests.decrementAndGet()
      authenticated.set(false)
      ownerToken = null
      state.compareAndSet(InUse, Available)
    }
  }

  def authenticateForUser(userCtx: UserContext): Unit = {
    authenticated.set(true)
    ownerToken = userCtx.sessionToken
  }
}

case class UserContext(userId: String, sessionToken: String, permissions: Set[String])

class ConnectionPool(config: PoolConfig, target: String)(implicit ec: ExecutionContext) {
  private val connections = new ConcurrentHashMap[Int, PooledConnection]()
  private val connectionCounter = new AtomicInteger(0)
  private val poolLock = new Object()

  def initialize(): Unit = {
    for (_ <- 0 until config.maxSize) {
      createConnection()
    }
  }

  private def createConnection(): PooledConnection = {
    val id = connectionCounter.getAndIncrement()
    val channel = ManagedChannelBuilder.forTarget(target)
      .useTransportSecurity()
      .build()
    val conn = new PooledConnection(channel, id)
    connections.put(id, conn)
    conn
  }

  def acquire(userCtx: UserContext): Option[PooledConnection] = {
    val iter = connections.values().iterator()
    while (iter.hasNext) {
      val conn = iter.next()
      if (conn.markInUse(userCtx.sessionToken)) {
        conn.authenticateForUser(userCtx)
        return Some(conn)
      }
    }
    None
  }

  def release(conn: PooledConnection, userCtx: UserContext): Unit = {
    conn.release(userCtx.sessionToken)
  }

  def executeWithConnection[T](userCtx: UserContext)(operation: PooledConnection => T): Option[T] = {
    acquire(userCtx) match {
      case Some(conn) =>
        try {
          val result = operation(conn)
          Some(result)
        } finally {
          release(conn, userCtx)
        }
      case None => None
    }
  }
}

class SecureGrpcService(pool: ConnectionPool)(implicit ec: ExecutionContext) {

  private val authCache = new ConcurrentHashMap[String, UserContext]()

  def handleRequest(sessionToken: String, requestData: String): Future[String] = {
    val promise = Promise[String]()

    Future {
      val userCtx = resolveUser(sessionToken)
      if (userCtx == null) {
        promise.failure(new SecurityException("Invalid session"))
      } else {
        pool.executeWithConnection(userCtx) { conn =>
          validateConnectionOwnership(conn, userCtx)
          performSecureOperation(conn, requestData, userCtx)
        } match {
          case Some(result) => promise.success(result)
          case None => promise.failure(new RuntimeException("No available connections"))
        }
      }
    }

    promise.future
  }

  private def validateConnectionOwnership(conn: PooledConnection, userCtx: UserContext): Unit = {
    // Check that the connection is authenticated for this user
    if (!conn.authenticated.get()) {
      throw new SecurityException("Connection not authenticated")
    }
    // Verify the owner token matches the current user
    if (conn.ownerToken != userCtx.sessionToken) {
      throw new SecurityException("Connection ownership mismatch")
    }
  }

  private def performSecureOperation(conn: PooledConnection, data: String, userCtx: UserContext): String = {
    // Simulate operation that relies on connection-level auth state
    if (conn.ownerToken != userCtx.sessionToken) {
      throw new SecurityException("Token mismatch - connection hijacked")
    }
    s"Result for ${userCtx.userId}: processed $data on connection ${conn.id}"
  }

  private def resolveUser(token: String): UserContext = {
    authCache.get(token)
  }

  def registerUser(ctx: UserContext): Unit = {
    authCache.put(ctx.sessionToken, ctx)
  }
}
